// Normaliza el aviso de error de n8n. Dos formas de entrada: un fallo en un
// nodo normal trae `execution`; un fallo del propio trigger trae `trigger`.
const e = $json.execution || {};
const t = $json.trigger || {};
const w = $json.workflow || {};
const err = e.error || t.error || {};
const mensaje = String(err.message || err.description || 'Error desconocido').slice(0, 1500);
const nodo = e.lastNodeExecuted || (err.node && err.node.name) || '';

// Anti-spam: el mismo fallo (workflow + nodo + mensaje) se notifica como
// mucho una vez por hora. Un Gmail sin credencial sondea cada minuto y, sin
// esto, mandaria 60 alertas por hora.
const VENTANA = 60 * 60 * 1000;
const store = $getWorkflowStaticData('global');
const vistos = store.alertas || {};
const ahora = Date.now();
for (const k of Object.keys(vistos)) { if (ahora - vistos[k].at > VENTANA) delete vistos[k]; }
const clave = (w.id || '') + '|' + nodo + '|' + mensaje.slice(0, 200);
const previo = vistos[clave];
const notificar = !previo;
vistos[clave] = previo ? { at: previo.at, silenciados: (previo.silenciados || 0) + 1 } : { at: ahora, silenciados: 0 };
store.alertas = vistos;

// Solo un booleano: el token nunca entra en los datos de la ejecucion.
const token = [$env.TELEGRAM_TOKEN_ALERTAS, $env.TELEGRAM_NOTICIAS_TOKEN, $env.TELEGRAM_TOKEN_EMAIL,
  $env.TELEGRAM_TOKEN_LABORAL, $env.TELEGRAM_TOKEN_MARCA].find((v) => /^\d+:[\w-]+$/.test(String(v || '').trim()));
const telegram_listo = !!token && /^-?\d+$/.test(String($env.TELEGRAM_CHAT_ID || '').trim());

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cuando = new Date().toLocaleString('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
let texto = `🚨 <b>Fallo en «${esc(w.name || 'workflow')}»</b>\n<i>${cuando}</i>\n\n`;
if (nodo) texto += `Nodo: <b>${esc(nodo)}</b>\n`;
texto += `Error: <code>${esc(mensaje.slice(0, 600))}</code>`;
if (e.url) texto += `\n\n<a href="${esc(e.url)}">Abrir la ejecución en n8n</a>`;
texto += `\n\n<i>Los fallos repetidos se silencian durante 1 hora.</i>`;

return [{ json: {
  workflow_id: String(w.id || ''),
  workflow_name: String(w.name || ''),
  execution_id: String(e.id || ''),
  execution_url: String(e.url || ''),
  node: nodo,
  mode: String(e.mode || t.mode || ''),
  message: mensaje,
  notificar,
  telegram_listo,
  texto,
} }];

